@dataclass
class Plan:
    steps: List[str]
    reasoning: str

@dataclass
class ExecutionResult:
    success: bool
    output: str
    error: Optional[str] = None
    code: Optional[str] = None

class VerificationStatus(Enum):
    SUCCESS = 'success'
    NEEDS_REFINEMENT = 'needs_refinement'
    FAILED = 'failed'

print("Dataclasses definies : Plan, ExecutionResult, VerificationStatus (SUCCESS, NEEDS_REFINEMENT, FAILED)")

class Coder:
    def __init__(self, llm: LLMClient):
        self.llm = llm

    def generate_code(self, plan: Plan, context: str) -> str:
        steps_text = '\n'.join(f"{i+1}. {s}" for i, s in enumerate(plan.steps))

        prompt = f"""Tu es un programmeur Python expert. Genere du code pour executer ce plan.

CONTEXTE:
{context}

PLAN:
{steps_text}

Genere UNIQUEMENT du code Python executable entre balises ```python ... ```
Le DataFrame est disponible dans la variable 'df'.
Utilise print() pour afficher les resultats.

Code:"""

        response = self.llm.generate(prompt, temperature=0.2)

        # Extract code
        match = re.search(r'```python\s*(.*?)\s*```', response, re.DOTALL)
        if match:
            return match.group(1).strip()
        return response

print("Classe Coder definie : generation de code Python a partir d'un plan d'analyse")

class Executor:
    def __init__(self, df: pd.DataFrame):
        self.df = df
        self.namespace = {'df': df, 'pd': pd, 'np': np, 'print': print}

    def execute(self, code: str) -> ExecutionResult:
        import sys
        from io import StringIO

        old_stdout = sys.stdout
        sys.stdout = StringIO()

        try:
            exec(code, self.namespace)
            output = sys.stdout.getvalue()
            return ExecutionResult(success=True, output=output, code=code)
        except Exception as e:
            output = sys.stdout.getvalue()
            return ExecutionResult(success=False, output=output, error=str(e), code=code)
        finally:
            sys.stdout = old_stdout

print("Classe Executor definie : execution securisee de code Python avec capture stdout")

class Verifier:
    def __init__(self, llm: LLMClient):
        self.llm = llm

    def verify(self, question: str, result: ExecutionResult) -> Tuple[VerificationStatus, str]:
        if not result.success:
            return VerificationStatus.FAILED, f"Erreur d'execution: {result.error}"

        prompt = f"""Verifie si ce resultat repond a la question.

QUESTION: {question}

RESULTAT:
{result.output[:1000]}

Reponds par:
- SUCCESS si le resultat est complet et correct
- NEEDS_REFINEMENT si le resultat est partiel mais prometteur
- FAILED si le resultat ne repond pas du tout

Verdict:"""

        response = self.llm.generate(prompt, temperature=0.1).upper()

        if 'SUCCESS' in response:
            return VerificationStatus.SUCCESS, "Resultat valide"
        elif 'REFINEMENT' in response:
            return VerificationStatus.NEEDS_REFINEMENT, "Necessite des ajustements"
        return VerificationStatus.FAILED, "Resultat insuffisant"

print("Classe Verifier definie : validation des resultats (SUCCESS / NEEDS_REFINEMENT / FAILED)")

class FileAnalyzer:
    """Analyse déterministe de fichiers de données avant les tours ADK."""

    SUPPORTED = {'.csv': 'csv', '.json': 'json', '.xlsx': 'excel'}

    def analyze_csv(self, path: str) -> FileMetadata:
        df = pd.read_csv(path)
        columns = []
        for name in df.columns:
            info = {
                'name': name,
                'dtype': str(df[name].dtype),
                'missing_pct': round(df[name].isna().mean() * 100, 2),
            }
            if pd.api.types.is_numeric_dtype(df[name]):
                info['stats'] = {
                    'min': float(df[name].min()),
                    'max': float(df[name].max()),
                    'mean': float(df[name].mean()),
                }
            columns.append(info)
        return FileMetadata(
            filename=Path(path).name,
            format='csv',
            size_bytes=os.path.getsize(path),
            num_rows=len(df),
            num_columns=len(df.columns),
            columns=columns,
            sample_data=df.head(3).to_dict('records'),
        )

    def generate_context(self, meta: FileMetadata) -> str:
        lines = [
            f"Fichier: {meta.filename}",
            f"Format: {meta.format}",
            f"Taille: {meta.size_bytes / 1024:.1f} KB",
            f"Lignes: {meta.num_rows}, Colonnes: {meta.num_columns}",
        ]
        for column in (meta.columns or [])[:5]:
            lines.append(f"  - {column['name']} ({column['dtype']})")
        return "\n".join(lines)

print("FileAnalyzer prêt : profil CSV déterministe sans appel LLM caché")

## 4. Planner-Coder-Verifier sur Google ADK

Les trois rôles de raisonnement sont désormais de vrais `google.adk.agents.Agent`, exécutés dans des sessions distinctes par un `Runner` :

- **Planner ADK** : appelle obligatoirement l'outil déterministe `get_file_schema`, puis produit un plan structuré ;
- **Coder ADK** : transforme ce plan en code Pandas visible et exécutable ;
- **Verifier ADK** : confronte la sortie à la question et rend un verdict actionnable.

L'**Executor** reste local : ADK porte les rôles LLM et leurs événements, tandis que le code généré demeure inspectable. Les anciennes classes synchrones basées sur `LLMClient` ne sont plus utilisées par le pipeline du workshop ; `LLMClient` reste seulement dans les exercices qui demandent d'étendre un composant historique.

