def evaluate_multi(n_tr, mu0, mu1, S0, S1, n_seeds=20, n_test=1000):
    res = {name: [] for name in models}
    for s in range(n_seeds):
        Xtr, ytr = make_pair(n_tr, mu0, mu1, S0, S1, 100 + s)
