def grad_norm(T, scaled):
    torch.manual_seed(0)
    ls = torch.randn(64, 10, requires_grad=True)
    lt = torch.randn(64, 10)
    kl = F.kl_div(F.log_softmax(ls / T, 1), F.softmax(lt / T, 1), reduction="batchmean")
    if scaled:
        kl = kl * (T * T)
    g, = torch.autograd.grad(kl, ls)
    return g.norm().item()

