def phrase_en_bow(phrase, vocab_size, word2idx):
    v = np.zeros(vocab_size)
    for t in tokeniser(phrase):
        if t in word2idx:
            v[word2idx[t]] += 1.0
    s = v.sum()
    if s > 0:
        v = v / s
    return v

