def to_pil(t):
    return Image.fromarray((t.clamp(0, 1) * 255).byte().cpu().permute(1, 2, 0).numpy())

def detect_persons(model, tensor, conf=0.25):
    r = model(np.asarray(to_pil(tensor)), imgsz=IMGSZ, conf=conf, verbose=False)[0]
    return [xyxy.tolist() for xyxy, cl in zip(r.boxes.xyxy.cpu(), r.boxes.cls.cpu()) if int(cl) == 0]

def iou(d, g):
    ix0, iy0 = max(d[0], g[0]), max(d[1], g[1])
    ix1, iy1 = min(d[2], g[2]), min(d[3], g[3])
    inter = max(0.0, ix1 - ix0) * max(0.0, iy1 - iy0)
    uni = (d[2] - d[0]) * (d[3] - d[1]) + (g[2] - g[0]) * (g[3] - g[1]) - inter
    return inter / uni if uni > 0 else 0.0

def eval_recall(model, tensors, gt_lists, tgt_idx, conf=0.25):
    """Recall de la CIBLE (porteur) et des TEMOINS (autres pietons) sur une liste d'images."""
    n = hit = oth_hit = oth_tot = 0
    for i, t in enumerate(tensors):
        det = detect_persons(model, t, conf=conf)
        gt_all = gt_lists[i]
        n += 1
        if any(iou(d, gt_all[tgt_idx[i]]) >= 0.5 for d in det):
            hit += 1
        for j, g in enumerate(gt_all):
            if j == tgt_idx[i]:
                continue
            oth_tot += 1
            if any(iou(d, g) >= 0.5 for d in det):
                oth_hit += 1
    return hit / n, (oth_hit / oth_tot if oth_tot else float("nan"))

def inbox_conf(net, T, B):
    """Confiance 'personne' maximale, moyennee sur les images, dans la boite cible."""
    v = []
    with torch.no_grad():
        for i in range(T.shape[0]):
            t = raw_out(net, T[i:i + 1])
            s, xy = t[0, 4], t[0, :2]
            ins = (xy[0] > B[i, 0]) & (xy[0] < B[i, 2]) & (xy[1] > B[i, 1]) & (xy[1] < B[i, 3])
            v.append(float(s[ins].max()) if int(ins.sum()) else 0.0)
    return float(np.mean(v))

print("primitives pretes : detect_persons / eval_recall / inbox_conf")

def stationnaire(n):
    """Deux tons stationnaires (8 et 21 cycles sur la fenetre)."""
    tt = np.arange(n) / n
    return np.sin(2 * np.pi * 8 * tt) + 0.6 * np.sin(2 * np.pi * 21 * tt)

def doppler(n):
    """Chirp decroissant canonique (Donoho-Johnstone) : sinus de frequence (1+eps)/(eps+t)."""
    tt = np.arange(1, n + 1) / n
    eps = 0.05
    return np.sqrt(n / 8) * np.sin(2 * np.pi * (1 + eps) / (eps + tt))

def heavisine(n):
    """Deux sinusoides + deux echelons (Donoho-Johnstone) : le cas mixte."""
    tt = np.arange(1, n + 1) / n
    return 4 * np.sin(4 * np.pi * tt) - np.sign(tt - 0.3) - np.sign(0.72 - tt)

# normalisation a puissance 1 (comparabilite des SNR entre bancs)
signals = {}
for name, fn in [("Stationnaire", stationnaire), ("Doppler", doppler), ("HeaviSine", heavisine)]:
    s = fn(N).astype(float)
    signals[name] = s / np.sqrt(np.mean(s ** 2))

# provenance : HeaviSine doit etre bit-exact contre la reference PyWavelets
h_ref = np.asarray(pywt.data.demo_signal("HeaviSine", N))
h_err = np.max(np.abs(heavisine(N) - h_ref))
d_ref = np.asarray(pywt.data.demo_signal("Doppler", N))
d_cos = float(
    (signals["Doppler"] / np.linalg.norm(signals["Doppler"]))
    @ (d_ref / np.linalg.norm(d_ref))
)
print(f"provenance HeaviSine vs pywt.data : maxdiff = {h_err:.2e}  (bit-exact)")
print(f"provenance Doppler    vs pywt.data : similarite cosinus = {d_cos:.4f}")

def marche(kind, N=256):
    """Motifs a orientation CONNUE (N multiple de 2, requis par la periodization)."""
    yy, xx = np.mgrid[0:N, 0:N] / N
    if kind == "constante":
        return np.ones((N, N)) * 7.0
    if kind == "marche_verticale":        # discontinuite selon x -> un bord VERTICAL
        return (xx > 0.5).astype(float)
    if kind == "marche_horizontale":      # discontinuite selon y -> un bord HORIZONTAL
        return (yy > 0.5).astype(float)
    if kind == "marche_diagonale":
        return ((xx + yy) > 1.0).astype(float)
    raise ValueError(kind)


print(f"{'motif':22s} {'max|cH|':>10s} {'max|cV|':>10s} {'max|cD|':>10s}   part de l'energie de detail")
for kind in ["constante", "marche_verticale", "marche_horizontale", "marche_diagonale"]:
    _, (bH, bV, bD) = dwt2(marche(kind), DB4)
    m = [np.max(np.abs(b)) for b in (bH, bV, bD)]
    e = np.array([np.sum(b ** 2) for b in (bH, bV, bD)])
    tot = e.sum()
    if tot < 1e-18:
        part = "  (energie nulle : image constante, controle negatif OK)"
    else:
        part = f"  {100 * e[0] / tot:5.1f}% {100 * e[1] / tot:5.1f}% {100 * e[2] / tot:4.1f}%"
    print(f"{kind:22s} {m[0]:10.2e} {m[1]:10.2e} {m[2]:10.2e}{part}")

XI0 = 3.0 * np.pi / 4.0        # frequence centrale a l'echelle 0 (convention Bruna-Mallat), rad/px
SIGMA0 = 0.8                   # enveloppe spatiale a l'echelle 0, px
SLANT = 0.5                    # retrecissement transversal (directionnalite)
SIGMA_PHI_PX = 0.8 * 2 ** (J - 1)   # fenetre basse frequence, px


def grille(M):
    """Frequences en rad/echantillon sur la grille FFT periodique."""
    n = np.fft.fftfreq(M) * 2 * np.pi
    return np.meshgrid(n, n, indexing="ij")


def morlet_fft(j, theta, M=SHAPE[0]):
    """Spectre du morlet analytique : gaussienne anisotrope a pic unique en +xi,
    corrigee d'admissibilite, normee L2."""
    w1, w2 = grille(M)
    c, s = np.cos(theta), np.sin(theta)
    wt = c * w1 + s * w2                  # axe de modulation
    wn = -s * w1 + c * w2                 # axe transverse
    xi = XI0 / 2 ** j
    sig = SIGMA0 * 2 ** j                 # l'enveloppe s'elargit comme l'echelle

    def enveloppe(dt, dn):
        return np.exp(-0.5 * sig ** 2 * (dt ** 2 + dn ** 2 / SLANT ** 2))

    K = np.exp(-0.5 * sig ** 2 * xi ** 2)      # reponse du pic a la frequence nulle
    psi = enveloppe(wt - xi, wn) - K * enveloppe(wt, wn)
    return psi / np.sqrt((psi ** 2).sum() / (M * M))   # norme L2 unitE


def phi_fft(M=SHAPE[0]):
    w1, w2 = grille(M)
    return np.exp(-0.5 * SIGMA_PHI_PX ** 2 * (w1 ** 2 + w2 ** 2))


# banc : un psi par (j, theta) ; normes et reponse DC residuelle
PSI = {(j, k): morlet_fft(j, k * np.pi / L) for j in range(J) for k in range(L)}
PHI = phi_fft()
normes = {(j, k): float((PSI[(j, k)] ** 2).sum() / SHAPE[0] ** 2) for j in range(J) for k in range(L)}
dc_res = {(j, k): float(PSI[(j, k)][0, 0]) for j in range(J) for k in range(L)}
print(f"normes L2 des {len(PSI)} psi : min={min(normes.values()):.4f} max={max(normes.values()):.4f} (cible 1.0)")
print(f"reponse DC residuelle : max |psi_hat(0,0)| = {max(abs(v) for v in dc_res.values()):.2e} (corrigee)")

def conv_c(x, h):
    """Convolution circulaire par un filtre donne en domaine Fourier - champ COMPLEXE."""
    return np.fft.ifft2(np.fft.fft2(x) * h)


def scattering(x):
    """Transformee de scattering 2D from scratch, pleine resolution, decimation finale.
    Renvoie un dict : 'S0' -> (8,8), ('S1', j, k) -> (8,8), ('S2', j1, k1, j2, k2) -> (8,8)."""
    out = {"S0": (conv_c(x, PHI).real)[:: 2 ** J, :: 2 ** J]}
    for (j1, k1), h1 in PSI.items():
        u1 = np.abs(conv_c(x, h1))                 # module du champ complexe
        out[("S1", j1, k1)] = (conv_c(u1, PHI).real)[:: 2 ** J, :: 2 ** J]
        u1_c = np.fft.fft2(u1)
        for (j2, k2), h2 in PSI.items():
            if j2 <= j1:
                continue
            u2 = np.abs(np.fft.ifft2(u1_c * h2))
            out[("S2", j1, k1, j2, k2)] = (conv_c(u2, PHI).real)[:: 2 ** J, :: 2 ** J]
    return out


def descripteur(x):
    """Tous les coefficients concatenes, ordre S0 puis S1 puis S2 (l'ordre de la reference)."""
    s = scattering(x)
    parts = [s["S0"].ravel()]
    parts += [s[("S1", j, k)].ravel() for j in range(J) for k in range(L)]
    parts += [s[("S2", j1, k1, j2, k2)].ravel()
              for j1 in range(J) for k1 in range(L)
              for j2 in range(J) for k2 in range(L) if j2 > j1]
    return np.concatenate(parts)


im_test = rng.standard_normal(SHAPE)
n_s1, n_s2 = J * L, sum(1 for j1 in range(J) for j2 in range(J) if j2 > j1) * L * L
d = descripteur(im_test)
print(f"S0 : 1 carte 8x8 | S1 : {n_s1} cartes | S2 : {n_s2} cartes")
print(f"une image 32x32 ({SHAPE[0]*SHAPE[1]} pixels) -> un descripteur de {d.shape[0]} coefficients")

### Lecture

La selectivite est nette, lisible et **conforme a la regle du vecteur d'onde** :

- marche verticale -- qui varie le long de l'axe horizontal -- excite l'angle pi/2 (~69 % de l'energie S1) ;
- marche horizontale -- qui varie le long de l'axe vertical -- excite l'angle 0 (~69 %) ;
- marche diagonale (triangle `tril_indices`) presente **trois bords** : gauche (vertical), bas (horizontal), et diagonale (j=i). La mesure distribue l'energie entre 0 (0.31, bord horizontal du triangle), pi/2 (0.31, bord vertical), **3pi/4 (0.29, bord diagonal j=i)** -- et ne place que 0.09 sur l'angle pi/4, qui n'a pas de bord d'orientation correspondante dans l'image test. C'est exactement ce que prevoit la regle du vecteur d'onde pour les trois orientations presentes :
  - bord diagonal j=i : vecteur d'onde (1,-1) -> 3pi/4 -> 0.29 (detecte) ;
  - bords vertical (gauche) et horizontal (bas) : contributions sur 0 et pi/2 -> 0.31 chacun ;
  - **absence** de bord d'orientation pi/4 dans l'image test -> 0.09 (l'angle reste quasi muet, ce qui est le signe que le scattering ne fabrique pas d'energie la ou il n'y a pas de structure).

Le test `tril_indices` n'est donc pas un cas d'« absence de diagonale » -- il est un cas de **plusieurs bords d'orientations differentes** superposes dans la meme image. L'argmax reste sur pi/2 ici parce que les deux bords vertical+horizontal pèsent chacun 0.31 (les contributions du bord diagonal s'ajoutent sur 3pi/4). En general, un front isole a 45 degres concentre son energie sur k=1 ou k=3 ; ici l'angle 3pi/4 est detectable (0.29), ce qui illustre la regle plutot qu'il ne l'invalide. Le scattering << voit >> les orientations comme la pyramide de WS-00b, mais en continu (4 angles ici, L=8 dans l'exercice 1) et **apres** module : la carte S1(j,theta) dit ou est le contour oriente theta, dans une forme deja stable par translation. Ce sont exactement ces cartes que le classifieur du §6 consomme.

## 5. Validation croisée contre kymatio : trois preuves complémentaires

La référence est `kymatio` (frontend numpy), J=2, L=4, 32×32 — les mêmes bornes, importé **uniquement pour la validation croisée**, comme `pywt` dans WS-00a/b. Trois preuves, chacune isolée d'une chose différente :

1. **Traduction** : répliquer le pipeline de la référence opération par opération (ses primitives recodées, **ses filtres injectés**) → si l'allclose passe coefficient par coefficient, c'est que notre moteur — convolutions, module, décimation spectrale, moyenne — est exact ;
2. **Écriture alternative** : la même cascade en une passe pleine résolution (décimation finale seulement, notre moteur du §2) → l'écart restant mesure ce que la décimation précoce de la référence change exactement ;
3. **Famille indépendante** : nos morlets de §1 contre leurs filtres → les coefficients diffèrent (une famille paramétrée n'est pas une base unique), mais les deux descripteurs doivent présenter **le même régime borné d'invariance**.

# preuve 3 : famille independante - la meme loi d'invariance des deux cotes
def S1_S2_mine(x):
    s = scattering(x)
    v1 = np.concatenate([s[("S1", j, k)].ravel() for j in range(J) for k in range(L)])
    v2 = np.concatenate([s[("S2", j1, k1, j2, k2)].ravel()
                         for j1 in range(J) for k1 in range(L)
                         for j2 in range(J) for k2 in range(L) if j2 > j1])
    return v1, v2


def S1_S2_kym(x):
    S = kym.scattering(x.astype("float32"))
    return S[1:1 + J * L].ravel(), S[1 + J * L:].ravel()


def invariance_par_ordre(x, decalages=(1, 2, 4, 8)):
    r1m, r2m = S1_S2_mine(x)
    r1k, r2k = S1_S2_kym(x)
    lignes = []
    for d_ in decalages:
        xt = np.roll(x, (d_, d_), axis=(0, 1))
        e1m = np.linalg.norm(S1_S2_mine(xt)[0] - r1m) / np.linalg.norm(r1m)
        e2m = np.linalg.norm(S1_S2_mine(xt)[1] - r2m) / np.linalg.norm(r2m)
        e1k = np.linalg.norm(S1_S2_kym(xt)[0] - r1k) / np.linalg.norm(r1k)
        e2k = np.linalg.norm(S1_S2_kym(xt)[1] - r2k) / np.linalg.norm(r2k)
        lignes.append((d_, e1m, e1k, e2m, e2k))
    return lignes


print(f"{'decalage':>9} | {'S1 (nord)':>10} | {'S1 kymatio':>11} | {'S2 (nord)':>10} | {'S2 kymatio':>11}")
for d_, a, b, c, e in invariance_par_ordre(x0):
    print(f"{d_:>7}px | {a:>10.4f} | {b:>11.4f} | {c:>10.4f} | {e:>11.4f}")

def descripteurs_batch(images):
    full, s1_only = [], []
    for x in images:
        s = scattering(x)
        f1 = np.concatenate([s[("S1", j, k)].ravel() for j in range(J) for k in range(L)])
        s1_only.append(f1)
        full.append(np.concatenate([s["S0"].ravel(), f1] +
                                   [s[("S2", j1, k1, j2, k2)].ravel()
                                    for j1 in range(J) for k1 in range(L)
                                    for j2 in range(J) for k2 in range(L) if j2 > j1]))
    return np.array(full), np.array(s1_only)


X_pix_tr, X_pix_te = ims[tr_i].reshape(len(tr_i), -1), ims[te_i].reshape(len(te_i), -1)
X_full_tr, X_s1_tr = descripteurs_batch(ims[tr_i])
X_full_te, X_s1_te = descripteurs_batch(ims[te_i])

# test translate : +-2 px alterne, periodique aux bords
