def psnr(ref, test, peak=255.0):
    """PSNR en dB (peak = 255 : images 8 bits) -- definition WS-00b."""
    mse = np.mean((ref - test) ** 2)
    return 10 * np.log10(peak ** 2 / mse) if mse > 0 else float("inf")


